def json_tile_to_runtime(value: Any, label: str = "tile") -> tuple[int, int]:
    if not isinstance(value, list) or len(value) != 2 or not all(isinstance(item, int) for item in value):
        raise ValueError(f"{label} must be integer [row,col]")
    row, col = value
    return col, row


def runtime_tile_to_json(value: tuple[int, int]) -> list[int]:
    return [value[1], value[0]]


class ReadOnlyQueryEngine:
    def __init__(self, facts_path: Path = NORMAL_LOW_STAR_FACTS, evidence_path: Path = EVIDENCE_CONTEXT):
        facts = json.loads(facts_path.read_text(encoding="utf-8"))
        rows = facts.get("operators") if isinstance(facts, dict) else facts
        self.operators = {row["operator_id"]: row for row in rows}
        self.evidence = json.loads(evidence_path.read_text(encoding="utf-8"))
        self.range_transformer = ApproximateRealRangeTransformer()

    def _base(self, evidence_status: str) -> dict[str, Any]:
        return {
            "data_version": DATA_VERSION,
            "mechanics_version": MECHANICS_VERSION,
            "evidence_status": evidence_status,
            "applicability": "R8-1 ordinary-mode 1-3 star debug configuration under the current public runtime.",
            "unknowns": [],
        }

    def _operator(self, operator_id: str) -> dict[str, Any]:
        row = self.operators.get(operator_id)
        if row is None:
            raise ValueError(f"unknown operator {operator_id}")
        qualification = row.get("qualification") or {}
        if qualification.get("normal_mode") is not True or not 1 <= row["identity"]["rarity"] <= 3:
            raise ValueError(f"operator is outside ordinary 1-3 star domain: {operator_id}")
        return row

    def _declared_configuration_matches(self, row: dict[str, Any], declared: Any) -> bool:
        expected = row.get("debug_configuration")
        if not isinstance(expected, dict) or not isinstance(declared, dict):
            return False
        if row.get("qualification", {}).get("eligible_for_debug") is not True:
            return False
        if expected.get("legal_for_debug") is not True:
            return False
        required_keys = ["rarity", "phase_index", "level", "potential_level", "trust"]
        if expected.get("skill_level_index") is not None:
            required_keys.append("skill_level_index")

from __future__ import annotations

from typing import Protocol


class RangeTransformer(Protocol):
    def covered_tiles(
        self,
        *,
        origin: tuple[int, int],
        offsets: tuple[tuple[int, int], ...],
        direction: str,
    ) -> set[tuple[int, int]]:
        """Convert canonical range offsets into map tiles for one facing direction."""


class CanonicalSyntheticRangeTransformer:
    """Synthetic-only orientation rule; it makes no claim about Arknights' rule.

    Offsets are defined for RIGHT. RIGHT=(dx,dy), DOWN=(-dy,dx), LEFT=(-dx,-dy),
    and UP=(dy,-dx), with x increasing right and y increasing down.
    """

    _directions = {"RIGHT", "DOWN", "LEFT", "UP"}

    def covered_tiles(
        self,
        *,
        origin: tuple[int, int],
        offsets: tuple[tuple[int, int], ...],
        direction: str,
    ) -> set[tuple[int, int]]:
        if direction not in self._directions:
            raise ValueError(f"Unsupported synthetic direction: {direction}")
        def rotate(dx: int, dy: int) -> tuple[int, int]:
            if direction == "RIGHT": return dx, dy
            if direction == "DOWN": return -dy, dx
            if direction == "LEFT": return -dx, -dy
            return dy, -dx
        return {(origin[0] + rotate(dx, dy)[0], origin[1] + rotate(dx, dy)[1]) for dx, dy in offsets}


class ApproximateRealRangeTransformer:
    """Real raw range cells in the fixture's bottom-left field coordinates."""

    _directions = {"RIGHT", "DOWN", "LEFT", "UP"}

    def covered_tiles(
        self,
        *,
        origin: tuple[int, int],
        offsets: tuple[tuple[int, int], ...],
        direction: str,
    ) -> set[tuple[int, int]]:
        if direction not in self._directions:
            raise ValueError(f"Unsupported real direction: {direction}")
        def rotate(row: int, col: int) -> tuple[int, int]:
            if direction == "RIGHT": return col, row
            if direction == "DOWN": return row, -col
            if direction == "LEFT": return -col, -row
            return -row, col
        return {
            (origin[0] + rotate(row, col)[0], origin[1] + rotate(row, col)[1])
            for row, col in offsets
        }

def _process_area_cast(self, state: SimulationState, stage: Stage, cast: _PendingAreaCast,
                       pending_area_hits: list[_PendingAreaHit]) -> None:
    source = state.active_enemies.get(cast.source_id)
    if source is None or source.hidden:
        self._emit(state, EventType.ENEMY_ABILITY_CANCELLED, source=cast.source_id,
                   target=cast.target_id, reason="SOURCE_UNAVAILABLE")
        return
    candidate = (
        state.active_enemies.get(cast.target_id)
        if cast.target_is_neutral
        else state.deployed_operators.get(cast.target_id)
    )
    if candidate is None or (cast.target_is_neutral and candidate.hidden):
        self._emit(state, EventType.ENEMY_ABILITY_CANCELLED, source=cast.source_id,
                   target=cast.target_id, reason="TARGET_UNAVAILABLE_BEFORE_PROJECTILE_CREATION")
        if source.area_hit_time is not None and source.area_hit_time <= cast.time + cast.delay_seconds + self._EPSILON:
            source.area_hit_time = None
            source.area_hit_radius = None
        return
    locked_position = self._enemy_position(stage, candidate) if cast.target_is_neutral else candidate.tile
    source.area_hit_position = locked_position
    self._emit(state, EventType.PROJECTILE_BORN, source=cast.source_id, target=cast.target_id,
               locked_position=locked_position, delay=cast.delay_seconds, radius=cast.range_radius)
    pending_area_hits.append(_PendingAreaHit(
        cast.time + cast.delay_seconds, cast.source_id, locked_position,
        cast.range_radius, source.atk * cast.atk_scale, cast.damage_type,
    ))

def _process_area_hit(self, state: SimulationState, stage: Stage, hit: _PendingAreaHit) -> None:
    for enemy in tuple(state.active_enemies.values()):
        if not enemy.is_neutral:
            continue
        enemy_position = self._enemy_position(stage, enemy)
        if hypot(hit.position[0] - enemy_position[0], hit.position[1] - enemy_position[1]) > hit.radius + self._EPSILON:
            continue
        damage = (
            arts_damage(hit.damage, enemy.magic_resistance)
            if hit.damage_type == "ARTS"
            else hit.damage if hit.damage_type == "TRUE" else physical_damage(hit.damage, enemy.defense)
        )
        self._damage_enemy(state, enemy, hit.source_id, damage, kind=hit.damage_type)
    for operator in tuple(state.deployed_operators.values()):
        if hypot(hit.position[0] - operator.tile[0], hit.position[1] - operator.tile[1]) > hit.radius + self._EPSILON:
            continue
        damage = (
            arts_damage(hit.damage, operator.magic_resistance)
            if hit.damage_type == "ARTS" else physical_damage(hit.damage, operator.defense)
        )
        operator.hp -= damage
        self._emit(state, EventType.ENEMY_ABILITY_HIT, source=hit.source_id,
                   target=operator.operator_id, amount=damage, kind=hit.damage_type,
                   locked_position=hit.position)
        if operator.hp <= 0:
            self._remove_operator(state, operator.operator_id, death=True)
    source = state.active_enemies.get(hit.source_id)
    if source is not None and source.area_hit_time is not None and source.area_hit_time <= state.time + self._EPSILON:
        source.area_hit_time = None
        source.area_hit_position = None
        source.area_hit_radius = None

